{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "A close analogue retaining the 2,3-dichlorophenylpiperazine amide core showed excellent brain penetrability in mice with brain-to-plasma ratios of 6- to 20-fold after oral and intravenous dosing, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "NGB 2904, which shares the dichlorophenylpiperazine benzamide scaffold, entered the brain quickly and demonstrated high brain penetration after intravenous administration, supporting the query's CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "JJC 4-077, another dichlorophenylpiperazine amide analogue, entered the brain quickly and showed high brain penetration after intravenous dosing, reinforcing the scaffold's CNS permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A structurally related benzamide with a basic amide side chain and heteroaryl substituent achieved a brain/plasma ratio of 1.3 in rats and was classified as good penetration, supporting the query's ability to access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A radiolabeled benzamide with a basic amine amide accumulated significantly in monkey brain in planar imaging studies, providing cross-species evidence that this amide/basic-amine class crosses the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: high-transfer direct CNS penetration evidence from close analogues sharing the dichlorophenylpiperazine amide scaffold (brain-to-plasma ratios up to 6-20x, rapid brain uptake in rodents and monkey) outweighs the moderate physicochemical prior and supports meaningful CNS access for the query.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "No explicit P-gp/BCRP efflux assay for the query; however, close analogues with the same dichlorophenylpiperazine amide core show high brain exposure despite potential transporter liability.",
    "The alkene linker may introduce metabolic instability, but this affects duration rather than initial CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

